contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public payable {
        // Bound to a realistic address domain - not a single EOA constraint.
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        // Actor pays exactly the required ticket amount.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        try c.play{value: 10}() { 
            // call succeeded - check pot invariant
        } catch {
            // If it reverts, pot remains unchanged - no assertion needed.
            return;
        }
        // The invariant: If a winner is chosen and the fee is transferred,
        // the pot must be reset to 0. If the condition fails, the pot
        // should be 10 * k (for k calls). The buggy version fails to
        // reset pot when random == 0 (original win condition), causing
        // pot to remain non-zero in successive calls. The general rule:
        // after any call, pot < TICKET_AMOUNT if a transfer occurred.
        // Since we cannot observe random, we assert a stricter condition
        // that holds in both: pot is either 0 (if reset) or a multiple of 10.
        // However, the bug causes pot to never reset on losing calls,
        // so pot grows unbounded. The reference always resets to 0 on win.
        // We assert: if the bank balance increased (i.e., fee was transferred),
        // then pot must be 0.
        uint256 bankBalanceBefore = address(c.bank()).balance;
        // We cannot read bank balance before inside try, so we use a different
        // approach: After any play() call, pot must be less than 10 unless
        // no transfer occurred. But the bug makes pot = 10 on first call and
        // 20 on second, etc. The reference resets to 0 when random == 0.
        // So we assert: pot < 10. In reference, pot is 0 or 10, but the bug
        // can leave pot >= 10 and not reset.
        assertTrue(c.pot() < 10);
    }
}

