pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0) && player != address(c) && player.code.length == 0);
        vm.deal(player, 20);
        uint expectedPotAfterOneCall;

        // first call
        vm.prank(player);
        try c.play{value: 10}() { expectedPotAfterOneCall = c.pot(); } catch { expectedPotAfterOneCall = 0; }

        // second call by same player, same block context (can't control timestamp/difficulty precisely but fuzzer explores)
        vm.prank(player);
        try c.play{value: 10}() { } catch { }

        uint finalPot = c.pot();
        // Rule: pot after two calls cannot exceed 10 if first call reset it, or 20 if first call did not.
        // But the bug leaves pot at 20 when the original would have reset after the second call.
        // The correct version ensures pot is either 0 or 10 after any single call, so after two calls max is 20.
        // However, when the second call's random matches the mutant's inverted condition while the first did not,
        // the pot becomes 20 instead of 0, which the reference never allows.
        assertTrue(finalPot != 20 || expectedPotAfterOneCall == 0);
    }
}

