pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint208 times) public {
        uint n = bound(uint256(times), 1, 20);
        address alice = address(0xA11CE);
        address bob = address(0xB0B);
        vm.deal(alice, 10 ether);
        vm.deal(bob, 10 ether);

        uint expectedPot = 0;
        for (uint i = 0; i < n; i++) {
            address actor = (i % 2 == 0) ? alice : bob;
            vm.prank(actor);
            c.play{value: 10}();
            // Derive the random outcome using the same block-dependent scheme.
            // We emulate the block context inside the VM: the fuzzer drives
            // block.timestamp and block.difficulty implicitly. We do not need to
            // compute "random" here; we simply observe the state directly.

            // Update our expected pot based on the actual state after the play:
            // - If pot is non-zero, the previous play did not win, so pot = previousPot + 10.
            // - If pot is zero, the previous play won, so pot was reset to 0.
            // Since we cannot predict the random outcome in the test, we adjust
            // expectedPot by reading the on-chain pot after each play:
            uint actualPot = c.pot();
            if (actualPot == 0) {
                // Win occurred: pot was reset to 0.
                expectedPot = 0;
            } else {
                // No win: pot increased by ticket amount (10).
                expectedPot = actualPot;
            }
        }

        // After all iterations, the actual pot must match the tracked expectedPot
        // Both the reference and the buggy contract track this correctly because
        // we compute expectedPot from the actual on-chain state; however, this
        // assertion itself is always true. To catch the bug, we assert a stronger
        // invariant: if a win occurred (pot became 0 at least once), then the final
        // pot must be less than n * 10, but more importantly, we need to observe
        // the difference in pot. Actually we observe directly: after any win,
        // immediately check that pot is 0.
        // We re-run with a different approach: after each play, if a win happened
        // (pot became 0), the reference set it to 0; the buggy left it as previous
        // pot - FEE_AMOUNT (which is positive). So we check after every interaction
        // whether a win occurred, and if so, pot must be 0.
        // We cannot easily detect a win from outside, but we can use the property
        // that pot after a win is either 0 (reference) or >0 (buggy). So we loop
        // again and assert pot is 0 whenever we suspect a win. However, the fuzzer
        // controls block.timestamp and difficulty, so we can force a win by looping
        // until we get random == 0. That's not possible without vm.roll. Instead,
        // we rely on the fuzzer to eventually produce a win. The property is:
        // pot is always either 0 or monotonically increasing? No.
        // The difference is: after a win, pot is reset to 0 in reference, but buggy
        // sets pot = oldPot - FEE_AMOUNT. So we can check that after any play,
        // if pot became 0, then the previous pot must have been nonzero (a win
        // occurred). That is trivial. Let's formulate the exact invariant that
        // reference satisfies and buggy violates: "pot is never equal to
        // oldPot + TICKET_AMOUNT - FEE_AMOUNT after a play." No.
        // Correct invariant: "After any play where the outcome is a win (random == 0),
        // the resulting pot is exactly 0." The buggy contract sets it to
        // oldPot - FEE_AMOUNT, which is >0. Since we cannot observe random,
        // we can fuzz the block parameters to make win and then check pot afterwards.
        // We will use try/catch to see if the transaction succeeded, but that's
        // not needed. We'll simply call play multiple times, and after each play,
        // check that pot != FEE_AMOUNT? No. The buggy pot after a win = oldPot - 1.
        // Since oldPot >= 10, buggy pot >= 9. So we can check that if pot > 0,
        // it must be at least 10? No. Better: we can check that pot is never
        // equal to 9, 19, 29, ...? Too specific.
        // Instead, we use the fact that the reference always resets pot to 0 on win,
        // so after any play, pot either becomes 0 or increases by 10. In the buggy
        // contract, after a win, pot becomes oldPot - 1, which is a decrease,
        // not to 0. So we can assert: after each play, either pot == 0 OR
        // pot >= previousPot + 10 (i.e., pot increased by at least 10).
        // The buggy violates this because after a win, pot = previousPot - 1,
        // which is a decrease, not to 0. But a win also causes transfers that
        // reduce pot to 0, so pot becomes 0. Wait, the buggy contract still
        // transfers the entire pot - FEE to msg.sender, so the pot after transfer
        // would be whatever remains. In the buggy, after transfer, the contract's
        // balance is drained, but pot variable is not updated to 0. So pot
        // retains the old value minus FEE_AMOUNT, while the contract's actual
        // ether balance is 0 (or FEE_AMOUNT?). The buggy contract still transfers
        // (pot - FEE_AMOUNT) to msg.sender, and FEE_AMOUNT to bank. So the entire
        // pot variable's value minus FEE_AMOUNT is sent out, but the pot variable
        // is not reduced to reflect the transfer. Then in subsequent plays,
        // pot continues to accumulate incorrectly. Therefore, the buggy pot
        // after a win is actually >0. The reference pot after a win is 0.
        // So we can check: there exists some point where pot is >0 and then
        // later becomes 0 without any transfer? No, the only way pot becomes 0
        // in reference is a win. In buggy, pot never becomes 0 (unless initial).
        // So we can assert: "pot is never >0 after a win." We can check this
        // by looping many plays, and after each play, if pot == 0, it's fine.
        // But we need to assert that pot never becomes, say, 9. So we assert
        // that pot is always a multiple of 10? No, reference pot is either 0
        // or multiples of 10. Buggy pot can be 9, 19, etc. So we can assert:
        // pot % 10 == 0.
        uint finalPot = c.pot();
        assertTrue(finalPot % 10 == 0, "pot must remain a multiple of 10");
    }
}

