contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n) public {
        // Admissible domain: 1 to 20 plays to keep runtime manageable
        vm.assume(n >= 1 && n <= 20);
        // Fund and execute n plays, tracking total paid in
        uint256 totalPaid = 0;
        for (uint8 i = 0; i < n; i++) {
            address player = address(uint160(uint256(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            totalPaid += 10;
        }
        // Property: pot must never exceed total tickets paid (represents unclaimed tickets only)
        assertTrue(c.pot() <= totalPaid);
    }
}

