pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 seed, address player) public {
        vm.assume(player != address(0) && player != address(this) && player != address(c));
        vm.deal(player, 10 ether);

        // Drive the contract to a state where it has some pot and we can attempt a win
        vm.prank(player);
        c.play{value: 10}();

        uint pot_before = c.pot();
        // Only meaningful if pot is non-zero (we put in 10, no win yet)
        vm.assume(pot_before > 0);

        // Arrange the environment so that keccak256(...) % 2 == 0 (win) happens.
        // We cannot control block.timestamp/difficulty freely, but we can brute-force seed via sender until win.
        // However, the fuzzer can't directly set 'random'. We'll allow it to try many times; if no win, skip.
        // To guarantee a win, we manipulate timestamp and difficulty? vm.warp and vm.roll don't guarantee %2==0.
        // Instead, we trust the fuzzer to find a seed where random==0. We'll run many attempts.
        // For a property test, we need a GENERAL rule. The rule: IF play() succeeds AND a transfer to player occurred (win), THEN pot must be 0.
        // We detect win by checking if player's balance increased by (pot_before + 9 - 1) = pot_before + 9? Wait, pot_before includes the 10 just added. On win, player gets pot_before - 1. So player balance increases by pot_before - 1.
        // Better: just check if pot decreased after the second play, meaning a win happened. But we need exact rule.

        // We'll call play again with sufficient gas and ETH, and record pot after.
        vm.deal(player, 10);
        uint bal_before = player.balance;
        vm.prank(player);
        try c.play{value: 10}() {
            uint pot_after = c.pot();
            // If play succeeded and pot decreased (win occurred), assert pot_after == 0.
            // But the rule must hold for evERY input. If play didn't result in a win, pot might not be 0, so we skip assertion.
            if (pot_after < pot_before + 10) { // pot_before + 10 is the value after adding msg.value without payout. If pot_after < that, payout occurred.
                assertTrue(pot_after == 0, "pot must be zero after a win");
            }
        } catch {
            // If play reverts, ignore.
        }
    }
}

