pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 callCount) public {
        // Bound callCount to a reasonable number of play attempts to avoid runaway loops;
        // the domain remains wide enough for the fuzzer to trigger the bug.
        callCount = uint8(bound(callCount, 1, 20));
        for (uint8 i = 0; i < callCount; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            try c.play{value: 10}() {} catch {}
        }
        // In the reference contract, pot can be 0 or a multiple of 10 (>=10).
        // In the mutant, pot can become 1 after a losing play, violating the property.
        // assertTrue checks that pot is never exactly 1.
        assertTrue(c.pot() != 1);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }
