import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playsBeforeWin) public {
        // Bound the number of losing plays before the winning play to a reasonable range.
        // The loop below simulates playsBeforeWin calls that lose (random forced to 1) and then a final call that wins (random forced to 0).
        // We bound to avoid excessive gas consumption.
        bound(playsBeforeWin, 0, 10);

        // Fund the caller with enough ether for the plays.
        address player = address(0x1234);
        vm.deal(player, 1000 ether);

        // Simulate the sequence: first playsBeforeWin losing plays.
        // On each losing play we manipulate the random result by making it odd (random = 1).
        // The reference implementation computes random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender))) % 2;
        // By setting block.difficulty to a value that, given the fuzzed timestamp and msg.sender, yields an odd hash,
        // we can force a loss. We use a brute-force: we call until random is 1 by trying different block.timestamp values.
        // However, since the fuzzer provides playsBeforeWin and the random is deterministic, we can't directly control it without cheatcodes.
        // Instead, we rely on the fuzzer to explore inputs where some plays lose due to natural random outcomes.
        // For the losing plays we don't care about the outcome as long as pot increases; the key is the final winning play.
        // We'll just execute playsBeforeWin calls with the required msg.value, letting natural randomness decide win/loss.
        // After those calls, we need to ensure the final call is a win to test the property.
        // To guarantee a win, we manipulate block.difficulty and block.timestamp such that the uint of the hash is even.
        // We can use vm.roll to influence block.difficulty (prevrandao) if we can set it directly, but vm.difficulty is forbidden.
        // We cannot use vm.difficulty. We can only use vm.warp and vm.roll. We'll use vm.roll to set block.number, which doesn't affect block.difficulty.
        // The random uses block.difficulty and block.timestamp. We cannot set block.difficulty without the forbidden vm.difficulty.
        // So we cannot force a win. The fuzzer must find a sequence where the last call naturally wins.
        // We'll let the fuzzer try many inputs; some will have the required sequence.
        // The property we test: after every call to play(), if the call resulted in a win (detected by checking if pot was reset),
        // then pot must either be 0 (reference) or 1 (mutant). For the reference, it's always 0. For the mutant, it's 1.
        // So we assert that pot is never equal to 1 after any play(). The reference will pass, the mutant will fail for some winning call.
        for (uint i = 0; i < playsBeforeWin; i++) {
            vm.prank(player);
            c.play{value: 10}();
        }

        // Final play: it might or might not win.
        vm.prank(player);
        c.play{value: 10}();

        // After the final play, the invariant is: pot must not be 1.
        // The reference never sets pot to 1; the mutant sets pot to 1 on wins.
        assertTrue(c.pot() != 1);
    }
}

