contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 seed, uint64 timestamp, uint64 difficulty) public {
        // restrict to plausible block values
        vm.assume(timestamp > 0);
        vm.warp(timestamp);
        vm.roll(difficulty);

        // fund a player and call play
        address player = makeAddr("player");
        vm.deal(player, 10);
        vm.prank(player);
        try c.play{value: 10}() {
            // if play did not revert, check the invariant
            uint potAfter = c.pot();
            bool isWin = (potAfter == 0);
            // The general rule: if the play call succeeded, the contract holds the invariant that
            // either pot is zero (indicating a payout occurred) or the random result was 1 (no payout).
            // However, since we cannot read random, the invariant we assert is stronger:
            // After a successful non-reverting play() call, pot MUST be either 0 or 10.
            // The bug causes pot to become 10 - 1 = 9 when a winning payout occurs, violating this.
            assertTrue(potAfter == 0 || potAfter == 10, "pot must be 0 or 10 after successful play");
        } catch {
            // if play reverted (e.g., random==0 and bank transfer failed because bank is an EOA with no code),
            // the contract state is untouched; no invariant to check.
        }
    }
}

