pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 sentValue, uint64 timestamp, uint64 difficulty) public {
        // Bound sentValue to exactly TICKET_AMOUNT so play() does not revert on require
        bound(sentValue, 10, 10);
        // Make the sender an arbitrary address with enough Ether
        address actor = address(uint160(uint256(keccak256(abi.encode(timestamp, difficulty)))));
        vm.deal(actor, sentValue);
        // Manipulate block environment to influence the random outcome
        vm.warp(timestamp);
        vm.roll(difficulty);
        // Record pot before, then call play()
        uint256 potBefore = c.pot();
        vm.prank(actor);
        c.play{value: sentValue}();
        uint256 potAfter = c.pot();
        // The pot growth attributable to this call is potAfter - potBefore (capped at sentValue).
        // This must be strictly less than sentValue, because at least FEE_AMOUNT is deducted on a win,
        // or the sent amount simply accumulates on a loss. The bug never resets pot, allowing it to equal sentValue.
        assertTrue(potAfter - potBefore < sentValue);
    }
}

