pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 numPlaysBefore, uint64 roll, uint64 fuzzSender) public {
        // numPlaysBefore >= 1 to ensure there is some non-winning play that builds pot
        vm.assume(numPlaysBefore >= 1);
        vm.assume(roll < 100);  // keep block.difficulty influence reasonably wide

        // Set up block context to influence randomness
        vm.roll(roll);
        vm.warp(fuzzSender);

        // Generate distinct senders for each play to avoid nonce/tx ordering issues
        address[5] memory senders;
        senders[0] = address(uint160(fuzzSender));
        for(uint i = 1; i < 5; i++) {
            senders[i] = address(uint160(uint256(keccak256(abi.encode(fuzzSender, i)))));
        }

        // Perform numPlaysBefore plays from different senders
        uint senderIdx = 0;
        for (uint i = 0; i < numPlaysBefore && i < 5; i++) {
            address player = senders[senderIdx++];
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
        }

        // Record pot before final play
        uint potBefore = c.pot();

        // Perform one more play that could be a win
        address finalPlayer = address(uint160(uint256(keccak256(abi.encode(fuzzSender, "final")))));
        vm.deal(finalPlayer, 10 ether);
        vm.prank(finalPlayer);
        c.play{value: 10}();

        uint potAfter = c.pot();

        // General rule: After any play(), pot is either 0 (if a win occurred and was paid out)
        // or it is at least TICKET_AMOUNT (10) because pot accumulates at least the new stake.
        // The bug may leave pot non-zero but less than TICKET_AMOUNT after a win.
        assertTrue(potAfter == 0 || potAfter >= 10);
    }
}

