pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed1, uint256 seed2, uint256 timestamp1, uint256 timestamp2) public {
        // Bound timestamps to plausible future values and ensure they differ
        vm.assume(timestamp1 != timestamp2);
        vm.assume(timestamp1 >= block.timestamp && timestamp2 >= block.timestamp);
        // Ensure seeds produce non-winning outcomes (random != 0, i.e. odd)
        vm.assume(seed1 % 2 == 1);
        vm.assume(seed2 % 2 == 1);
        uint256 ticket = 10;
        address alice = address(0x1000);
        vm.deal(alice, 2 * ticket);

        // First play — must be non-winning to keep pot
        vm.startPrank(alice);
        vm.warp(timestamp1);
        // We must manipulate the randomness source; the only lever is timestamp and seed via external manipulation.
        // Since we cannot control block.difficulty easily, we brute-force: if the actual keccak produces winning (even), skip.
        // The fuzzer will find suitable timestamps where random is odd.
        bytes32 hash1 = keccak256(abi.encodePacked(timestamp1, block.difficulty, alice));
        vm.assume(uint256(hash1) % 2 == 1);
        c.play{value: ticket}();
        uint256 potAfterFirst = c.pot();
        vm.stopPrank();

        // Second play — also non-winning
        vm.startPrank(alice);
        vm.warp(timestamp2);
        bytes32 hash2 = keccak256(abi.encodePacked(timestamp2, block.difficulty, alice));
        vm.assume(uint256(hash2) % 2 == 1);
        c.play{value: ticket}();
        uint256 potAfterSecond = c.pot();
        vm.stopPrank();

        // After two non-winning plays, pot must be 2 * ticket (20) in reference; mutant never adds, so pot will be 0
        assertTrue(potAfterSecond == 2 * ticket);
    }
}

