pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 n) public {
        // Restrict n to a reasonable number of plays to keep it wide but feasible
        bound(n, 1, 20);
        // Ensure block.timestamp and block.difficulty are set so keccak256 randomness is deterministic per fork
        // but the fuzzer can control execution through n. We need deterministic randomness that always
        // yields 1 (i.e., random != 0) so pot never resets. We can set block.timestamp and block.difficulty
        // to fixed values that we know produce random=1 for any sender. Since random depends on
        // block.timestamp, block.difficulty, and msg.sender, we fix timestamp and difficulty to a known
        // pair that yields 1 for all senders. keccak256 output for (ts, difficulty, sender) mod 2 depends
        // on sender; we cannot guarantee it's always 1 for all senders. So we need to make the fuzzer
        // search over senders that yield 1. But the fuzzer supplies only n. To achieve a fuzz parameter
        // that decides the behaviour, we use a fuzzed address as the player and let the fuzzer find
        // a sender that always gives random=1. We'll use `address player` as a second fuzz parameter.
    }
}

