pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 playCount, uint48 initialPot, uint48 feePaid) public {
        // Bound to avoid overflow and keep loop size finite
        vm.assume(playCount <= 5);
        vm.assume(initialPot <= 1e12);
        vm.assume(feePaid <= 1e12);

        // Simulate a history of plays by initializing pot and fees paid (purely for invariant check)
        // We cannot directly set pot, so we'll use a cheat: deploy, then simulate plays.
        // Actually, we can only observe public state. So we'll just call play() a bounded number of times
        // and then check the invariant.

        address player = address(0x1234);
        for (uint8 i = 0; i < playCount; i++) {
            vm.deal(player, 10);
            vm.prank(player);
            // The play might revert if random is 1 (no win), but that's fine - we catch it.
            // The invariant must hold regardless of revert status.
            try c.play{value: 10}() {} catch {}
        }

        // Now check the invariant: pot <= address(c).balance + totalFeesPaid
        // totalFeesPaid is tricky: we don't have a public getter for it. But we can compute it by noting
        // that bank balance includes its initial 0 plus all fees transferred.
        // However, bank is an address; its balance might include other funds? No, only this contract sends to it.
        // So we can compute totalFeesPaid as bank.balance.
        uint256 pot = c.pot();
        uint256 contractBalance = address(c).balance;
        uint256 bankBalance = address(c.bank()).balance;

        // The invariant: pot <= contractBalance + bankBalance
        // In reference C, pot = contractBalance + (fees transferred) - (any pending? no, pot is reset on win).
        // Actually, after each win, pot = 0, contract balance = pot + fees? Let's reason:
        // When a play wins, pot is used to send pot - FEE to player and FEE to bank, then pot = 0.
        // So after win, contract balance = 0, pot = 0, bank balance = total fees.
        // Before a win, pot = sum of tickets purchased since last win.
        // contract balance = sum of tickets since last win.
        // So at any time, pot == contract balance, because each ticket adds 10 to pot and 10 to contract.
        // However, on the winning play, the contract transfers out all funds before resetting pot to 0.
        // So after the transfer, contract balance = 0, pot = 0.
        // Thus, always pot == contract balance.
        // The bug adds 1 to pot without adding to contract balance, so pot > contract balance.
        // Hence the invariant pot <= contractBalance holds for reference, but fails for bug.
        assertTrue(pot <= contractBalance);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint tickets, uint fee) public {
        require(tickets == 10);
        require(fee == 1);
        address user = address(this);
        uint potBefore;
        bool reverted = false;
        potBefore = c.pot();
        (bool success, ) = address(c).call{value: tickets}(abi.encodeWithSignature("play()"));
        if (!success) {
            reverted = true;
        }
        assert(reverted || c.pot() == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
